# %%
import getpass
import os
os.environ["DJ_IGNORE_CONFIG_FILE"] = "true"

from pathlib import Path
import datajoint as dj

# %% [markdown]
# # Setup

# %%
username = getpass.getuser()
home_directory = os.path.expanduser("~")
username, home_directory

# %%
# Path to djimaging
path_to_djimaging = f'{home_directory}/github/eulerlab/'

# Clone djimaging if you haven't downloaded it yet
# assert os.isdir(path_to_djimaging), 'Create target folder before cloning djimaging'
# # !cd {path_to_djimaging} && git clone git@github.com:eulerlab/djimaging.git

# Install djimaging if not done yet
# assert os.isdir(os.path.join(path_to_djimaging, 'djimaging')), 'Create target folder before cloning djimaging'
# # !cd {path_to_djimaging}/djimaging/ && sudo pip install -e .

# %%
def plot_if_data(table, method='plot1', **kwargs):
    """Call a plot method of a table, but only if the table has entries. Allows to use *Run all* on empty tables."""
    if len(table) == 0:
        print(f"{table.__class__.__name__} is empty, skip plotting.")
        return
    getattr(table, method)(**kwargs)

# %% [markdown]
# # Data Base

# %% [markdown]
# ## Prepare dj config

# %%
# Set config file
config_file = f'{home_directory}/datajoint/dj_{username}_conf.json'
assert os.path.isfile(config_file), f'Set the path to your config file: {config_file}'

# %%
# Define a schema name, by default made of your login name and the project name given to make_project.py
# It should start with ageuler and have some meaningful name after that
schema_name = f"ageuler_{username}___PROJECT__"

# %%
# Load configuration for user
dj.config.load(config_file)
print("schema_name:", schema_name)
dj.conn()

# %% [markdown]
# ## Create or load schema

# %%
# Import your own schema, which defines the tables you will have in your database and how they are connected.
from __SCHEMA_MODULE__ import *

# %% [markdown]
# ## Important note
#
# If the schema with the name `schema_name = f"ageuler_{username}___PROJECT__"` already exists, it is important that the schema definition here is the same as it was when the schema was created.
# If you did another tutorial first, and did not delete (=drop) the schema afterwards, this will not be the case, for example.
# Then you already have a schema with the same name but different tables. This can result in a variety of problems, so you either have to change the schema name here or drop the old schema first.
#
# Outside of this tutorial, in most cases, you want exactly one schema per project to never run into this problem.

# %%
from djimaging.utils.dj_utils import activate_schema

activate_schema(
    schema=schema,
    schema_name=schema_name,
    create_schema=True,
    create_tables=True,
)
schema

# %% [markdown]
# ## Diagram
#
# Shows all tables of your schema and how they depend on each other.

# %%
import warnings

with warnings.catch_warnings():
    warnings.simplefilter("ignore", FutureWarning)
    display(dj.Diagram(schema))

# %% [markdown]
# # Core: Data import
#
# The first tables describe *where* your data is and *how* to read it.
#
# - `UserInfo`: Who recorded the data and where the data folder is. Also defines how the folder structure maps to
#   animal, region, field, stimulus, and conditions.
# - `RawDataParams`: Parameters for reading the raw data files (e.g. which data type, which channels).

# %%
reference_root = Path(dj.config.get_store_spec('reference')['location'])

userinfo = {
    'experimenter': 'TestUser', # Replace this if you want to use your own data
    'data_dir': str(reference_root / 'Data/DataJointTestData/xy-RGCs'), # Replace the relative dataset path for your data
    'datatype_loc': 0,
    'animal_loc': 1,
    'region_loc': 2,
    'field_loc': 3,
    'stimulus_loc': 4,
    'cond1_loc': 5,
    'cond2_loc': 6,
    'cond3_loc': 7,
}

assert os.path.isdir(userinfo['data_dir'])

# %%
UserInfo().upload_user(userinfo)
UserInfo()

# %%
# Plot the data files in the selected folder
UserInfo().plot1(key=None, show_pre=False, show_raw=False, show_header=True)

# %%
RawDataParams().add_default()
RawDataParams()

# %% [markdown]
# ## Experiments and fields
#
# - `Experiment`: One entry per recorded animal/preparation, including meta data (animal, indicator, pharmacology).
# - `Field`: One entry per imaged field (a scan region of the recording), found by scanning the data folder.

# %%
Experiment().rescan_filesystem(verboselvl=2)
Experiment()

# %%
Field().rescan_filesystem(verboselvl=2)
Field()

# %%
# If you call plot1 on a djimaging table, it will plot the given key.
# If you pass key=None or no key it will pick a key at random.
# This is implemented for most core tables and can be useful to get a quick impression of the data.
plot_if_data(Field(), key=None)

# %% [markdown]
# ## Stimuli and presentations
#
# - `Stimulus`: Definitions of the stimuli you used (chirp, moving bar, noise, ...), including the stimulus trace
#   and how many triggers belong to one repetition.
# - `Presentation`: One entry per presentation of a stimulus in a field, with trigger times and scan info.
#   Contains the data that is shared by all ROIs of the field.

# %%
# To compute receptive fields, the noise stimulus trace must be loaded and set!
import h5py

noise_file = reference_root / 'Resources/Stimulus/noise.h5'

with h5py.File(noise_file, "r") as f:
    noise_stimulus = f['stimulusarray'][:].T.astype(int)

# %%
Stimulus().add_nostim(skip_duplicates=True)
Stimulus().add_chirp(spatialextent=1000, stim_name='gChirp', alias="chirp_gchirp_globalchirp", skip_duplicates=True)
Stimulus().add_chirp(spatialextent=300, stim_name='lChirp', alias="lchirp_localchirp", skip_duplicates=True)
Stimulus().add_noise(
    stim_name='noise',
    pix_n_x=20,
    pix_n_y=15,
    pix_scale_x_um=30,
    pix_scale_y_um=30,
    offset_x_um=-15,
    offset_y_um=-15,
    stim_path=noise_file,
    stim_trace=noise_stimulus,
    skip_duplicates=True,
)
Stimulus().add_movingbar(
    ntrigger_rep=1,
    trial_info=[dict(name=d, ntrigger=1) for d in (0, 180, 45, 225, 90, 270, 135, 315)],
    bardx=300,
    bardy=1000,
    velumsec=1000,
    tmovedurs=4.0,
    skip_duplicates=True,
)

# %%
# Add custom stimulus if needed
# Stimulus().add_stimulus(stim_name='my_stimulus', alias="stimname_stimnameabbr_alternativename", isrepeated=True, ntrigger_rep=6,
#                         trial_info=[dict(name=d, ntrigger=1) for d in range(1, 7)], skip_duplicates=True)

# %%
Stimulus()

# %%
Presentation().populate(processes=20, display_progress=True)
Presentation()

# %%
plot_if_data(Presentation(), key=None)

# %% [markdown]
# # Core: ROIs
#
# - `RoiMask`: The ROI mask of a field (which pixels belong to which ROI). Masks are drawn manually and/or
#   proposed by AutoROIs and saved to files, which are then loaded into the table.
# - `Roi`: One entry per ROI, derived from the masks.
#
# Without ROI masks, all following sections stay empty.

# %%
# If you have saved some of your AutoROIs ROI masks you can load them here.
RoiMask().rescan_filesystem(verboselvl=2, roi_mask_dir='AutoROIs')
RoiMask()

# %%
# Find all the fields that still require a ROI mask.
missing_fields = RoiMask().list_missing_field()
print(f"{len(missing_fields)} fields without ROI mask")

# %%
# Preload models so you only have to do it once
# Can also be None for all-manual ROIs, check the code for available models
try:
    from djimaging.tables.core.roi_mask import load_default_autorois_models
    autorois_models = load_default_autorois_models()
except ImportError:
    print("AutoROIs dependencies are not installed (extra 'autorois'), use manual ROIs only.")
    autorois_models = None

# %%
if len(missing_fields) > 0:
    field_key = missing_fields.pop()  # Pick one field

    # Load ROI canvas, draw the ROI mask, clean it if you want, shift if you want.
    # You can then save it to a file to be able to load it again later.
    roi_canvas = RoiMask().draw_roi_mask(field_key=field_key, canvas_width=30, autorois_models=autorois_models, roi_mask_dir='AutoROIs')
    roi_canvas.start_gui()
else:
    print("All fields have a ROI mask.")

